    /// <summary>SI value with 4 significant digits, e.g. "1.5 kW" is printed as "1500 W".</summary>
    public override string ToString() => ToString(null, null);
    public string ToString(IFormatProvider formatProvider) => ToString(null, formatProvider);
    public string ToString(string? format) => ToString(format, null);
    public string ToString(string? format, IFormatProvider? formatProvider) => QuantityFormatter.Format(_si, EnergyUnit.SI.Symbol, format, formatProvider);
    /// <summary>The value in <paramref name="unit"/>, e.g. "1.5 kW".</summary>
    public string ToString(EnergyUnit unit, string? format = null, IFormatProvider? formatProvider = null) => QuantityFormatter.Format(As(unit), unit.Symbol, format, formatProvider);

    /// <summary>
    /// The same value, shown in <paramref name="unit"/>: <c>$"{p.ToUnit(PressureUnit.Bar)}"</c> prints "2 bar". Values are always
    /// stored in SI, so this is a display wrapper - it converts back to Energy, but math on it needs the Energy first.
    /// </summary>
    public QuantityInUnit<Energy> ToUnit(EnergyUnit unit) => new(this, unit);

    /// <summary>The value in SI. (A decimal in EngineeringUnits; the same number as <see cref="SI"/> here.)</summary>
    [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
    public double AsSI => _si;

    /// <summary>Returns the same value: it is always stored in SI. (EngineeringUnits converts the unit here.)</summary>
    public Energy ConvertToSI() => this;

}

/// <summary>Writes {"Value": si, "Unit": "J"}. Reads that (any unit of Energy, by exact symbol) or a bare SI number - a unit of another quantity is rejected.</summary>
public sealed class EnergyJsonConverter : JsonConverter<Energy>
{
    public override Energy Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        => Energy.FromSI(QuantityJson.Read(ref reader, "Energy", EnergyUnit.BySymbol));

    public override void Write(Utf8JsonWriter writer, Energy value, JsonSerializerOptions options)
        => QuantityJson.Write(writer, value.SI, EnergyUnit.SI.Symbol);
}

public static partial class UnitMath
{
    [return: DimensionOf(nameof(value), PowerParameter = nameof(toPower))]
    public static UnknownUnit Pow(this Energy value, int toPower) => new(Math.Pow(value.SI, toPower));

    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this Energy value) => new(Math.Sqrt(value.SI));

    public static Energy Sum(this IEnumerable<Energy> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return Energy.FromSI(sum);
    }

    public static Energy Average(this IEnumerable<Energy> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Energy.FromSI(sum / count);
    }

    public static Energy Min(this IEnumerable<Energy> values) => Aggregate(values, Math.Min);
    public static Energy Max(this IEnumerable<Energy> values) => Aggregate(values, Math.Max);

    private static Energy Aggregate(IEnumerable<Energy> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Energy.FromSI(result);
    }
}
